function avatarMarkup(size){return S.avatarImage?'<img class="avatar-img" src="'+S.avatarImage+'" alt="Selected avatar" style="width:'+size+'px;height:'+size+'px">':'<span style="font-size:'+size+'px">'+(AVS[S.av]||AVS[0])+'</span>'}
