function chips(arr,key,cur,fmt){return'<div class="chips">'+arr.map(function(a,i){var val=key==="spec"||key==="track"?a:i,selected=cur===val,colorStyle=key==="patch"?' style="background:transparent;border-color:'+PATCH[i]+'"':'';return'<button class="chip '+(selected?"on":"")+(key==="patch"?" patch-chip":"")+'" data-set="'+key+'" data-v="'+esc(val)+'" aria-pressed="'+selected+'"'+colorStyle+'>'+(fmt?fmt(a,i):esc(a))+(selected?'<span class="apply-icon" aria-label="Applied">✓</span>':'')+'</button>'}).join("")+'</div>'}
function patchSvg(){return'<div class="patch-insignia"><div class="patch-preview" style="border-color:'+PATCH[S.patch]+';color:'+PATCH[S.patch]+';box-shadow:0 0 18px '+PATCH[S.patch]+'66">'+(SHAPES[S.shape]||SHAPES[0])+'</div><span class="patch-rank">'+esc(rank())+'</span></div>'}
function hub(){
return'<div class="card"><h1 style="font-size:26px">Build your astronaut profile</h1><p class="mut">Pick a callsign, avatar and patch. Your rank updates automatically as you earn XP. Everything saves on this device.</p>'
+'<div class="profile-insignia"><div class="avatar-preview">'+avatarMarkup(56)+'</div>'+patchSvg()+'</div>'
+'<label>Name</label><input type="text" id="f-name" maxlength="24" value="'+esc(S.name)+'">'
+'<label>Callsign</label><input type="text" id="f-call" maxlength="16" placeholder="e.g. Nova-7" value="'+esc(S.call)+'">'
+'<label>Avatar</label>'+chips(AVS,"av",S.avatarImage?-1:S.av,function(a){return a})+'<label for="f-avatar">Use an image from your device</label><input class="avatar-file" type="file" id="f-avatar" accept="image/*"><p class="mut">Choose a photo to use as your astronaut avatar.</p>'
+'<label>Mission patch colour</label>'+chips(PATCH,"patch",S.patch,function(a,i){return'<span style="color:'+a+'">● '+a+'</span>'})
+'<label>Patch shape</label>'+chips(SHAPES,"shape",S.shape,function(a){return a})

+'<label>Training track (optional)</label>'+chips(["13-17","18-25"],"track",S.track)

+'<div class="profile-actions"><button class="btn" data-act="saveprof">Save profile and enter Base</button><button class="btn alt profile-home-back" data-go="home">Home</button></div></div>'}
function tick(){var el=$("cd");if(!el)return;var d=new Date(Date.UTC(2026,11,14))-Date.now();if(d<0){el.textContent="Peak underway";return}
var s=Math.floor(d/1000);el.textContent=Math.floor(s/86400)+"d "+Math.floor(s%86400/3600)+"h "+Math.floor(s%3600/60)+"m "+s%60+"s"}
function ctl(){
var today=new Date().toDateString(),can=S.claimed!==today,last=S.done.length?LESSONS.filter(function(l){return l.id===S.done[S.done.length-1]})[0]:null;
var rec=last?"Because you finished “"+last.t.split(":")[0]+"”, try the Oxygen & Fuel mission in the Lab.":"Start with Orbital mechanics, then try the Oxygen & Fuel mission.";
return'<div class="card"><div class="row"><div><h2>Today in space</h2><p class="mut">Sample items. A full build would pull launch, ISS and sky-event APIs.</p></div><div style="text-align:right"><div class="big">'+S.streak+'🔥</div><span class="mut">day streak</span></div></div>'
+FEED.map(function(f){return'<p style="margin:8px 0"><span class="tag">'+f[0]+'</span> '+esc(f[1])+'</p>'}).join("")+'</div>'
+'<div class="card"><h3>Countdown: Geminid meteor shower peak (approx.)</h3><div class="big" id="cd"></div></div>'
+'<div class="grid"><div class="card"><h3>Daily challenge</h3><p class="mut">Finish one lesson or one mission today.</p><button class="btn" data-act="claim" '+(can?"":"disabled")+'>'+(can?"Claim +15 XP":"Claimed today")+'</button></div>'
+'<div class="card"><h3>Mission of the week</h3><p class="mut">Deliver the crew to Mars with fuel and oxygen to spare.</p><button class="btn mg" data-go="lab">Open Mission Lab</button></div></div>'
+'<div class="card"><h3>Recommended for you</h3><p class="mut">'+esc(rec)+'</p></div>'}
function acad(){
if(les){var l=LESSONS.filter(function(x){return x.id===les})[0],dn=S.done.indexOf(l.id)>-1;
return'<div class="card"><button class="btn alt" data-go="acad">Back</button><h2 style="margin-top:12px">'+esc(l.t)+'</h2><p class="mut">'+l.min+' min · '+l.xp+' XP</p><p>'+esc(l.body)+'</p><h3>Check: '+esc(l.q)+'</h3>'
+l.o.map(function(o,i){return'<button class="opt" data-lq="'+i+'">'+esc(o)+'</button>'}).join("")+(dn?'<p class="mut">Already completed. Retake for practice (no extra XP).</p>':'')+'</div>'}
var lvl=RANKS.map(function(r){return r[0]});
return'<div class="card"><h1 style="font-size:26px">Space Academy</h1><p class="mut">Bite-sized lessons. Levels unlock as you earn XP.</p></div>'
+LESSONS.map(function(l){var li=lvl.indexOf(l.lv),need=RANKS[li][1],lock=S.xp<need,dn=S.done.indexOf(l.id)>-1;
return'<div class="card"><div class="row"><div><h3>'+esc(l.t)+'</h3><span class="tag">'+l.lv+'</span> <span class="tag">'+l.min+' min</span> '+(dn?'<span class="tag" style="color:var(--ok)">Done</span>':'')+'</div>'
+'<button class="btn '+(lock?'alt':'')+'" '+(lock?'disabled':'data-les="'+l.id+'"')+'>'+(lock?'Needs '+need+' XP':'Start')+'</button></div></div>'}).join("")}
function testv(){
if(!quiz)return econCard()+supCard()+'<div class="card"><h1 style="font-size:26px">Flight readiness test</h1><p class="mut">Pre-flight check: 5 questions, 3 lives, 15 seconds each. Pass to launch.</p><button class="btn" data-act="qstart">Begin pre-flight check</button></div>';
if(quiz.end)return'<div class="card"><h2>'+(quiz.lives>0?"Cleared for launch":"Scrubbed")+'</h2><p>Score: '+quiz.score+' / '+quiz.bank.length+'</p>'+(quiz.cash?'<p><b>Earned '+quiz.earned+' credits. Spend them on the Base tab.</b></p>':'')+(quiz.miss.length?'<p class="mut">Review these in the Lab simulator: '+quiz.miss.map(esc).join("; ")+'</p>':'')+'<button class="btn" data-act="'+(quiz.cash?'sstart':'qstart')+'">Run it again</button></div>';
var q=quiz.bank[quiz.i];
return'<div class="card"><div class="row"><span>Lives: '+"❤️".repeat(quiz.lives)+'</span><span class="big" id="qt" style="font-size:24px">'+quiz.t+'</span></div><h2 style="margin-top:10px">'+esc(q.q)+'</h2>'
+q.o.map(function(o,i){var c=quiz.pick!=null?(i===q.a?"good":(i===quiz.pick?"bad":"")):"";return'<button class="opt '+c+'" data-qa="'+i+'" '+(quiz.pick!=null?'disabled':'')+'>'+esc(o)+'</button>'}).join("")
+(quiz.pick!=null?'<p class="mut">'+esc(q.e)+'</p><button class="btn" data-act="qnext">Next</button>':'')+'</div>'}
function qTimer(){clearInterval(tm);tm=setInterval(function(){if(!quiz||quiz.pick!=null||quiz.end)return;quiz.t--;var e=$("qt");if(e)e.textContent=quiz.t;if(quiz.t<=0)qAns(-1)},1000)}
function qAns(i){var q=quiz.bank[quiz.i];quiz.pick=i===-1?99:i;if(i===q.a){quiz.score++;gain(10,"sci");if(quiz.cash){S.cr=(S.cr||0)+25;quiz.earned+=25}}else{quiz.lives--;quiz.miss.push(q.q)}render()}
function labv(){
if(!lab)return'<div class="card"><h1 style="font-size:26px">Mission Lab: Mars transfer</h1><p class="mut">Cover 100 units of distance without running out of fuel or oxygen. Each day you pick a burn profile. Watch for events.</p><button class="btn" data-act="lstart">Launch simulation</button></div>';
function g(n,v,c){return'<div class="gauge"><span>'+n+' '+Math.max(0,v)+'</span><div class="bar"><i style="width:'+Math.max(0,Math.min(100,v))+'%;background:'+c+'"></i></div></div>'}
var h='<div class="card"><h2>Day '+lab.day+'</h2>'+g("Distance",lab.d,"var(--cy)")+g("Fuel",lab.f,"var(--am)")+g("Oxygen",lab.o,"var(--ok)")+'<p class="mut">'+esc(lab.msg)+'</p>';
if(lab.over)return h+'<h3>'+(lab.win?"Mars orbit achieved! +40 XP":"Mission failed: "+lab.why)+'</h3><button class="btn" data-act="lstart">Try again</button></div>';
if(lab.ev)return h+'<h3>Solar flare warning</h3><button class="opt" data-lev="shelter">Shelter in the storm cellar (−12 oxygen, safe)</button><button class="opt" data-lev="push">Push through (50% chance of −25 fuel from damage)</button></div>';
return h+'<button class="opt" data-lm="cruise">Cruise: +10 distance, −8 fuel, −10 oxygen</button><button class="opt" data-lm="boost">Boost: +18 distance, −16 fuel, −10 oxygen</button><button class="opt" data-lm="save">Conserve: +5 distance, −3 fuel, −6 oxygen</button></div>'}
function lStep(m){var L=lab;var t={cruise:[10,8,10],boost:[18,16,10],save:[5,3,6]}[m];L.d+=t[0];L.f-=t[1];L.o-=t[2];L.day++;L.msg="Day complete.";
if(L.day>4&&Math.random()<.2){L.o-=10;L.msg="Micrometeoroid hit: a small leak cost 10 oxygen."}
lEnd();if(!L.over&&!L.flare&&L.d>=45){L.flare=true;L.ev=true;L.msg="Alert from mission control."}render()}
function lEnd(){var L=lab;if(L.f<0||L.o<0){L.over=true;L.why=L.o<0?"crew ran out of oxygen.":"ship ran out of fuel.";gain(5,"eng")}else if(L.d>=100){L.over=true;L.win=true;gain(40,"nav");gain(0,"eng")}else if(L.day>30){L.over=true;L.why="the transfer window closed."}}
