var UP=[["react","Fission reactor",12,"+9 power per crew on power"],["recyc","Water recycler",10,"+4 water per crew on mining"],["hydro","LED hydroponics",10,"+4 food per crew in greenhouse"],["shield","Storm and radiation shielding",8,"Halves the damage from events"]];
