function dayNum(){return Math.floor((Date.now()-new Date().getTimezoneOffset()*60000)/864e5)}
function econPick(){var C=colony,k;if(C&&!C.over){k=["p","w","f"].sort(function(a,b){return C[a]-C[b]})[0]}else{k=["p","w","f"][dayNum()%3]}return{k:k,i:dayNum()%3}}
function econCard(){S.econ=S.econ||{};var today=new Date().toDateString(),E=S.econ,done=E.day===today,P=done?{k:E.k,i:E.i}:econPick(),Q=EC[P.k][P.i],nm={p:"power",w:"water",f:"food"},live=colony&&!colony.over;
return'<div class="card" style="border-color:var(--am)"><h2>Daily economy challenge</h2><p class="mut">Today’s colony problem: '+nm[P.k]+(live&&!done?' (your lowest supply right now)':'')+'. A new question every day. Correct answer: +20 XP'+(live?' and +5 RP for your colony':'')+'.</p><p>'+esc(Q[0])+'</p><h3>'+esc(Q[1])+'</h3>'+Q[2].map(function(o,j){var c=done?(j===Q[3]?"good":(j===E.pick?"bad":"")):"";return'<button class="opt '+c+'" data-ea="'+j+'" '+(done?"disabled":"")+'>'+esc(o)+'</button>'}).join("")+(done?'<p class="mut">'+esc(Q[4])+'</p><p><b>'+(E.ok?"+20 XP earned today.":"+5 XP for trying.")+' A new problem arrives tomorrow.</b></p>':'')+'</div>'}
function econAns(j){S.econ=S.econ||{};var today=new Date().toDateString();if(S.econ.day===today)return;var P=econPick(),Q=EC[P.k][P.i],ok=j===Q[3],live=colony&&!colony.over;S.econ={day:today,k:P.k,i:P.i,pick:j,ok:ok};
if(ok){gain(20,"surv");if(live)colony.rp+=5;toast("Correct! +20 XP"+(live?" and +5 RP":""))}else{gain(5,"surv");toast("Not quite. +5 XP for trying")}save();render()}
var SUP=[
{q:`How much of its water can the ISS recover and reuse?`,o:[`About 10%`,`About 50%`,`About 90% or more`],a:2,e:`Recycling humidity and urine lets the ISS reuse roughly 90 percent or more of its water.`},
{q:`Why plan to make rocket propellant on Mars?`,o:[`Launch mass from Earth is very expensive`,`It is more fun`,`Earth fuel is banned in space`],a:0,e:`Every kilogram launched costs a lot, so using local resources saves money and mass.`},
{q:`Which greenhouse plan lowers the risk of losing all food?`,o:[`One high-yield crop`,`Several different crops`,`No crops, only supplements`],a:1,e:`Diversifying crops spreads risk so one blight cannot wipe out the supply.`},
{q:`Why keep batteries or a power reserve during a dust storm?`,o:[`They bridge the gap when solar output drops`,`They make storms shorter`,`They attract sunlight`],a:0,e:`Stored energy keeps life support running while panels produce little.`},
{q:`Supplies are low. What should the colony do first?`,o:[`Use everything now`,`Ignore the problem`,`Cut non-essential use and ration`],a:2,e:`Rationing low-value use first stretches the supply at the least cost.`}];
function supCard(){var done=S.supDay===new Date().toDateString();return`<div class='card' style='border-color:var(--mg)'><div class='row'><h2>Supply run exam</h2><span class='tag'>${S.cr||0} credits</span></div><p class='mut'>Answer 5 logistics questions. Each correct answer earns 25 credits to spend in the Supply market on the Base tab.${done?' You already took it today, but you can earn more.':''}</p><button class='btn mg' data-act='sstart'>Start supply exam</button></div>`}
function buySup(k){var C=colony;if(!C||C.over)return;var b={p:30,w:25,f:25}[k],lv=Math.max(0,Math.min(100,C[k])),pr=Math.round(b*(1+(100-lv)/100));if((S.cr||0)<pr||C[k]>=100)return;S.cr-=pr;C[k]=Math.min(100,C[k]+20);save();toast('Bought +20 '+{p:'power',w:'water',f:'food'}[k]);render()}
var ml=null,MU=398600,R1=6771,R2=384400;
var SC=[
{t:`Slow pressure loss`,r:[`Cabin pressure 96 kPa, falling 1 kPa per hour`,`Oxygen and CO2 levels normal`,`Cold spot detected near Hatch B`],f:[`Micrometeoroid leak near Hatch B`,`CO2 scrubber failure`,`Coolant pump failure`],fa:0,s:[`Close Hatch B and isolate the module`,`Wait until pressure reaches 80 kPa`,`Vent the cabin to space`],sa:0,x:[`Apply a patch kit over the hole`,`Replace the CO2 filter`,`Restart the coolant pump`],xa:0,e:[`Falling pressure with a cold spot points to a leak, not a scrubber or pump problem.`,`Isolating the module protects the rest of the station and buys time.`,`A patch kit seals a small hole, which is the actual fault.`]},
{t:`Air quality alarm`,r:[`CO2 at 1.2 percent and rising`,`Cabin pressure normal`,`Scrubber fan reads 0 RPM`],f:[`Hull leak`,`CO2 scrubber failure`,`Battery overheating`],fa:1,s:[`Open every hatch`,`Switch to the backup scrubber and move crew to a clean module`,`Turn off the lights`],sa:1,x:[`Charge the battery`,`Patch the hull`,`Replace the scrubber fan motor`],xa:2,e:[`Rising CO2 with a stopped fan means the scrubber failed. Pressure is normal, so it is not a leak.`,`Backup air removal and moving the crew keeps everyone safe while you fix it.`,`The fan motor is the part that stopped, so that is what to replace.`]},
{t:`Overheating electronics`,r:[`Avionics at 48°C and rising`,`Coolant flow 0 L/min`,`Pump power draw 0 W`],f:[`Coolant pump failure`,`Micrometeoroid leak`,`CO2 scrubber failure`],fa:0,s:[`Shed non-essential electrical load to cut heat`,`Increase power to every system`,`Open the airlock`],sa:0,x:[`Patch the hull`,`Swap in the spare pump`,`Replace the CO2 filter`],xa:1,e:[`No flow and no pump power mean the pump is dead, so heat builds because nothing carries it away.`,`Cutting load reduces heat while you work.`,`Swapping the pump restores coolant flow.`]}];
document.addEventListener('keydown',function(e){if(ml&&ml.t==='rover'&&(e.code==='Space'||e.code==='ArrowUp')){ml.th=true;e.preventDefault()}});
document.addEventListener('keyup',function(e){if(ml&&ml.t==='rover'&&(e.code==='Space'||e.code==='ArrowUp'))ml.th=false});
document.addEventListener('input',function(e){if(e.target.id==='sl'&&ml&&ml.t==='orbit'){ml[ml.stage===1?'b1':'b2']=+e.target.value;var o=document.getElementById('ob');if(o)o.innerHTML=orbitPanel();var vv=document.getElementById('bv');if(vv)vv.textContent=(+e.target.value).toFixed(2)}});
document.addEventListener('keydown',function(e){if(ml&&ml.t==='dodge'){if(e.code==='ArrowLeft'){ml.L=1;e.preventDefault()}if(e.code==='ArrowRight'){ml.R=1;e.preventDefault()}}});
document.addEventListener('keyup',function(e){if(ml&&ml.t==='dodge'){if(e.code==='ArrowLeft')ml.L=0;if(e.code==='ArrowRight')ml.R=0}});
function dodgeView(){return `<div class='card'><div class='row'><h2>Asteroid dodge</h2><button class='btn alt' data-lab='back'>Abort</button></div><p class='mut'>Survive 20 seconds. Drag on the field, hold the buttons, or use the left and right arrow keys to steer.</p><canvas id='dg' width='320' height='420' style='width:100%;max-width:360px;display:block;margin:0 auto;border-radius:12px;touch-action:none'></canvas><div class='row' style='margin-top:10px'><button class='btn alt' id='dl' style='flex:1;min-height:56px;touch-action:none'>◀ Left</button><button class='btn alt' id='dr' style='flex:1;min-height:56px;touch-action:none'>Right ▶</button></div></div>`}
function dodgeInit(){var cv=document.getElementById('dg');if(!cv)return;var c=cv.getContext('2d'),W=cv.width,H=cv.height,sh={x:W/2},rocks=[],t=0,last=performance.now(),spawn=0;
function hold(id,k){var el=document.getElementById(id);el.addEventListener('pointerdown',function(e){e.preventDefault();ml[k]=1});['pointerup','pointerleave','pointercancel'].forEach(function(ev){el.addEventListener(ev,function(){ml[k]=0})})}
hold('dl','L');hold('dr','R');
function aim(e){var r=cv.getBoundingClientRect();sh.x=Math.max(14,Math.min(W-14,(e.clientX-r.left)/r.width*W))}
cv.addEventListener('pointerdown',aim);cv.addEventListener('pointermove',function(e){if(e.buttons||e.pointerType==='touch')aim(e)});
function step(now){if(!document.body.contains(cv)||ml.done)return;var dt=Math.min(.05,(now-last)/1000);last=now;t+=dt;
sh.x+=((ml.R?1:0)-(ml.L?1:0))*240*dt;sh.x=Math.max(14,Math.min(W-14,sh.x));
spawn-=dt;if(spawn<=0){spawn=.45-Math.min(.25,t/80);rocks.push({x:Math.random()*W,y:-20,r:10+Math.random()*14,v:120+Math.random()*90+t*4})}
var hit=false;rocks.forEach(function(k){k.y+=k.v*dt;var dx=k.x-sh.x,dy=k.y-(H-50);if(dx*dx+dy*dy<(k.r+10)*(k.r+10))hit=true});
rocks=rocks.filter(function(k){return k.y<H+40});
c.fillStyle='#060a14';c.fillRect(0,0,W,H);c.fillStyle='#cfe9ff';for(var i=0;i<30;i++){c.fillRect((i*97)%W,((i*53)+t*60)%H,1.5,1.5)}
c.fillStyle='#8a98bd';rocks.forEach(function(k){c.beginPath();c.arc(k.x,k.y,k.r,0,7);c.fill()});
c.fillStyle='#3de6ff';c.beginPath();c.moveTo(sh.x,H-70);c.lineTo(sh.x+12,H-38);c.lineTo(sh.x-12,H-38);c.closePath();c.fill();
c.fillStyle='#e6ecff';c.font='14px sans-serif';c.fillText('Time left '+Math.max(0,20-t).toFixed(1)+' s',12,22);
if(hit){fin(false,'An asteroid hit your ship after '+t.toFixed(1)+' seconds.');return}
if(t>=20){fin(true,'You flew through the asteroid field unharmed.');return}
requestAnimationFrame(step)}
requestAnimationFrame(step)}
function matchStart(){var P=[['Mars','Red planet'],['Jupiter','Great Red Spot storm'],['Saturn','Famous icy rings'],['Venus','Hottest planet']],cards=[];P.forEach(function(p,i){cards.push({k:i,t:p[0]},{k:i,t:p[1]})});
for(var i=cards.length-1;i>0;i--){var j=Math.floor(Math.random()*(i+1)),t=cards[i];cards[i]=cards[j];cards[j]=t}
ml={t:'match',done:false,cards:cards.map(function(c){return{k:c.k,t:c.t,show:false,done:false}}),open:[],moves:0,lock:false}}
function matchView(){var m=ml;return `<div class='card'><div class='row'><h2>Planet match</h2><button class='btn alt' data-lab='back'>Abort</button></div><p class='mut'>Match each world with its fact. Finish in 12 moves or fewer. Moves used: ${m.moves}</p><div class='grid' style='grid-template-columns:repeat(2,1fr)'>${m.cards.map(function(c,i){var up=c.show||c.done;return `<button class='opt' data-mc='${i}' style='text-align:center;margin:0;min-height:72px${c.done?';border-color:var(--ok);color:var(--ok)':''}'>${up?esc(c.t):'❓'}</button>`}).join('')}</div></div>`}
function matchFlip(i){var m=ml;if(!m||m.t!=='match'||m.lock||m.done)return;var c=m.cards[i];if(c.show||c.done)return;c.show=true;m.open.push(i);render();
if(m.open.length===2){m.moves++;var a=m.cards[m.open[0]],b=m.cards[m.open[1]];m.lock=true;setTimeout(function(){if(ml!==m)return;if(a.k===b.k){a.done=true;b.done=true}a.show=false;b.show=false;m.open=[];m.lock=false;if(m.cards.every(function(x){return x.done})){fin(true,'All pairs matched in '+m.moves+' moves.');return}if(m.moves>=12){fin(false,'Out of moves. You needed to finish within 12.');return}render()},700)}}
function labMain(){
if(ml){if(ml.done)return `<div class='card'><h2>${ml.win?'Mission complete':'Mission failed'}</h2>${ml.win&&ml.coins?`<div class='big'>+${ml.coins} 🪙</div>`:''}<p>${esc(ml.sum)}</p><p><b>${esc(ml.msg)}</b></p><div class='grid'>${ml.win?'':`<button class='btn' data-lab='${ml.t}'>Try again</button>`}<button class='btn alt' data-lab='back'>Back to Lab</button></div></div>`;if(ml.t==='rover')return roverView();if(ml.t==='orbit')return orbitView();if(ml.t==='dodge')return dodgeView();if(ml.t==='match')return matchView();return fixView()}
var live=colony&&!colony.over;
var M=[['rover','🛬 Rover landing','Fire the thrusters to touch down softly on Mars. Land slower than 4 m/s before the fuel runs out.','+40 coins'],['orbit','🌙 Orbit transfer','Plan two burns to move from low Earth orbit to the Moon’s distance, using real orbital math.',live?'+25 coins and +6 research points':'+25 coins'],['fix','🔧 Module repair','Read the sensors, find the fault and fix a failing station module. The problem is different each time.',live?'+25 to your lowest supply':'+30 coins'],['dodge','☄️ Asteroid dodge','Steer your ship through an asteroid field for 20 seconds without a hit. Drag, use the buttons or the arrow keys.','+20 coins'],['match','🪐 Planet match','Flip cards to match each world with its fact. A memory game with real science.','+20 coins']];
return `<div class='card'><h1 style='font-size:26px'>Mission Lab</h1><p class='mut'>Short skill missions. Succeed to earn rewards for your colony. ${live?'Your colony is running, so rewards go straight to it.':'Start a colony and rewards go straight to it. Until then you earn credits.'}</p></div>`+M.map(function(m){var dn=S.labDone&&S.labDone.d===new Date().toDateString()&&S.labDone[m[0]];return `<div class='card'><div class='row'><div><h3>${m[1]}</h3><p class='mut' style='margin:4px 0'>${m[2]}</p><span class='tag'${dn?` style='color:var(--ok);border-color:var(--ok)'`:''}>${dn?'Completed today':'Reward: '+m[3]}</span></div>${dn?`<button class='btn alt' disabled>Completed ✅</button>`:`<button class='btn' data-lab='${m[0]}'>Start</button>`}</div></div>`}).join('')}
function labInit(){if(ml&&ml.t==='rover'&&!ml.done)roverInit();if(ml&&ml.t==='dodge'&&!ml.done)dodgeInit()}
function reward(kind,win){var C=colony,live=C&&!C.over,sk=kind==='fix'?'eng':kind==='match'?'sci':'nav';S.labDay=new Date().toDateString();
if(!win){gain(10,sk);return '+10 XP for the attempt. Try again.'}
gain(30,sk);var td=new Date().toDateString();if(!S.labDone||S.labDone.d!==td)S.labDone={d:td};S.labDone[kind]=1;
if(kind==='dodge'||kind==='match'){S.cr=(S.cr||0)+20;ml.coins=20;save();return '+30 XP and +20 coins.'}if(kind==='rover'){S.cr=(S.cr||0)+40;ml.coins=40;save();return '+30 XP and +40 coins.'}if(kind==='orbit'){S.cr=(S.cr||0)+25;ml.coins=25;if(live)C.rp+=6;save();return '+30 XP and +25 coins'+(live?' and +6 research points for your colony.':'.')}
if(live){if(kind==='orbit'){C.rp+=6;return '+30 XP and +6 research points for your colony.'}
var k=['p','w','f'].sort(function(a,b){return C[a]-C[b]})[0];C[k]=Math.min(100,C[k]+25);return '+30 XP and +25 '+{p:'power',w:'water',f:'food'}[k]+' sent to your colony.'}
S.cr=(S.cr||0)+30;save();return '+30 XP and +30 credits. Start a colony to send rewards there.'}
function fin(win,sum){ml.done=true;ml.win=win;ml.sum=sum;ml.msg=reward(ml.t,win);render()}
function labAct(x){if((x==='rover'||x==='orbit'||x==='fix'||x==='dodge'||x==='match')&&S.labDone&&S.labDone.d===new Date().toDateString()&&S.labDone[x]){toast('Already completed today');return}
if(x==='back'){ml=null;render();return}
if(x==='rover'){ml={t:'rover',done:false,th:false};render();return}
if(x==='orbit'){ml={t:'orbit',stage:1,b1:2.5,b2:.4,done:false};render();return}
if(x==='fix'){fixStart();render();return}if(x==='dodge'){ml={t:'dodge',done:false,L:0,R:0};render();return}if(x==='match'){matchStart();render();return}
if(x==='fnext'){ml.st++;ml.pick=null;if(ml.st>=3){fin(ml.wrong<=1,ml.wrong<=1?'Module stabilized with '+ml.wrong+' mistake(s).':'Too many mistakes. The module was lost.')}else render();return}
if(x==='lock'){if(ml.stage===1){var o=oPre(R1,Math.sqrt(MU/R1)+ml.b1);if(!o||Math.abs(o.ra-R2)/R2>.05){toast('The far point must be within 5% of 384,400 km');return}ml.ra=o.ra;ml.stage=2;render()}
else{if(ml.pe>0&&Math.abs(ml.pe-ml.ra)<=.1*ml.ra)fin(true,'Circular orbit at the Moon’s distance. Transfer complete.');else toast('Orbit is not circular yet. Adjust burn 2.')}}}
function roverView(){return `<div class='card'><div class='row'><h2>Rover landing</h2><button class='btn alt' data-lab='back'>Abort</button></div><p class='mut'>Hold the thrust button (or press Space) to slow down. Gravity pulls you down at 3.7 m/s². Land slower than 4 m/s.</p><canvas id='rv' width='320' height='420' style='width:100%;max-width:360px;display:block;margin:0 auto;border-radius:12px;touch-action:none'></canvas><button class='btn' id='thr' style='width:100%;margin-top:10px;min-height:56px;touch-action:none'>Hold to thrust</button></div>`}
function roverInit(){var cv=document.getElementById('rv');if(!cv)return;var c=cv.getContext('2d'),W=cv.width,H=cv.height,st={alt:300,v:0,f:100,last:performance.now()};ml.th=false;
function press(on){return function(e){e.preventDefault();ml.th=on}}
['thr','rv'].forEach(function(id){var el=document.getElementById(id);el.addEventListener('pointerdown',press(true));['pointerup','pointerleave','pointercancel'].forEach(function(ev){el.addEventListener(ev,press(false))})});
function draw(){c.fillStyle='#060a14';c.fillRect(0,0,W,H);c.fillStyle='#cfe9ff';for(var i=0;i<30;i++){c.fillRect((i*97)%W,(i*53)%(H-60),1.5,1.5)}
c.fillStyle='#8c3b2a';c.fillRect(0,H-30,W,30);
var y=H-30-18-(Math.max(0,st.alt)/300)*(H-110);c.save();c.translate(W/2,y);
if(ml.th&&st.f>0){c.fillStyle='#ffb347';c.beginPath();c.moveTo(-6,10);c.lineTo(6,10);c.lineTo(0,24+Math.random()*8);c.fill()}
c.fillStyle='#3de6ff';c.beginPath();c.moveTo(0,-16);c.lineTo(12,10);c.lineTo(-12,10);c.closePath();c.fill();c.restore();
c.font='14px sans-serif';c.fillStyle='#e6ecff';c.fillText('Altitude '+Math.max(0,Math.round(st.alt))+' m',12,22);c.fillStyle=st.v<=4?'#5dffa3':'#ff6b6b';c.fillText('Speed '+st.v.toFixed(1)+' m/s (land under 4)',12,42);c.fillStyle='#8a98bd';c.fillText('Fuel',12,62);c.fillStyle='#ffb347';c.fillRect(50,54,Math.max(0,st.f)*1.2,8)}
function step(now){if(!document.body.contains(cv)||ml.done)return;var dt=Math.min(.05,(now-st.last)/1000);st.last=now;var th=ml.th&&st.f>0;st.v+=(3.7-(th?9:0))*dt;if(th)st.f-=10*dt;st.alt-=st.v*dt;
if(st.alt>400){fin(false,'You thrusted away from the landing zone.');return}
if(st.alt<=0){draw();var ok=st.v<=4;fin(ok,ok?'Touchdown at '+st.v.toFixed(1)+' m/s.':'Crashed at '+st.v.toFixed(1)+' m/s. The safe limit is 4 m/s.');return}
draw();requestAnimationFrame(step)}
requestAnimationFrame(step)}
function oPre(r,v){var e=v*v/2-MU/r;if(e>=0)return null;var a=-MU/(2*e);return{a:a,ra:2*a-r}}
function orbitPanel(){var s=118/R2,Fx=100,Fy=130,out='',txt='';
function el(rp,ra,col,dash){var a=Math.max(rp*s,2.5),b=Math.min(ra*s,210);return `<ellipse cx='${Fx+(b-a)/2}' cy='${Fy}' rx='${(a+b)/2}' ry='${Math.sqrt(a*b)}' fill='none' stroke='${col}' stroke-width='2'${dash?' stroke-dasharray=5,4':''}/>`}
if(ml.stage===1){var o=oPre(R1,Math.sqrt(MU/R1)+ml.b1);if(o){out=el(R1,o.ra,'#ffb347');txt='Burn 1 of '+ml.b1.toFixed(2)+' km/s gives a far point of '+Math.round(o.ra).toLocaleString()+' km. Target: 384,400 km.'+(Math.abs(o.ra-R2)/R2<=.05?' ✅ On target: press Execute.':'')}else txt='That burn is too strong: you would escape Earth.'}
else{out=el(R1,ml.ra,'#5b6b91',1);var a1=(R1+ml.ra)/2,va=Math.sqrt(MU*(2/ml.ra-1/a1)),e=(va+ml.b2)*(va+ml.b2)/2-MU/ml.ra;
if(e<0){var pe=2*(-MU/(2*e))-ml.ra;ml.pe=pe;out+=el(Math.max(pe,R1),ml.ra,'#3de6ff');txt='Burn 2 of '+ml.b2.toFixed(2)+' km/s lifts the low point to '+Math.round(Math.max(pe,0)).toLocaleString()+' km. Aim for a circle at '+Math.round(ml.ra).toLocaleString()+' km.'+(pe>0&&Math.abs(pe-ml.ra)<=.1*ml.ra?' ✅ Round enough: press Execute.':'')}else{ml.pe=-1;txt='That burn is too strong: you would escape.'}}
return `<svg viewBox='0 0 330 260' style='width:100%;max-width:420px;display:block;margin:0 auto' role='img' aria-label='Orbit diagram'><circle cx='${Fx}' cy='${Fy}' r='118' fill='none' stroke='#3a4a6e' stroke-dasharray=3,5 /><circle cx='${Fx}' cy='${Fy}' r='5' fill='#3de6ff'/><circle cx='${Fx+118}' cy='${Fy}' r='5' fill='#8a98bd'/>${out}</svg><p class='mut'>${txt}</p>`}
function orbitView(){var s1=ml.stage===1;return `<div class='card'><div class='row'><h2>Orbit transfer</h2><button class='btn alt' data-lab='back'>Abort</button></div><p class='mut'>${s1?'Step 1: from low Earth orbit, burn forward to raise the far point of your orbit to the Moon’s distance (grey dot).':'Step 2: at the far point, burn again to make the orbit round.'}</p><div id='ob'>${orbitPanel()}</div><label>${s1?'Burn 1':'Burn 2'}: <b id='bv' style='color:var(--cy)'>${(s1?ml.b1:ml.b2).toFixed(2)}</b> km/s</label><input type='range' id='sl' min='${s1?2.5:.4}' max='${s1?3.7:1.3}' step='0.01' value='${s1?ml.b1:ml.b2}' style='width:100%;height:40px;accent-color:#3de6ff'><button class='btn' data-lab='lock' style='margin-top:10px'>${s1?'Execute burn 1':'Execute burn 2'}</button><p class='mut'>Tip: a Hohmann transfer uses one burn to stretch the orbit and a second burn at the far point to make it round.</p></div>`}
function fixStart(){var s0=SC[Math.floor(Math.random()*SC.length)];
function mk(o,a){var idx=o.map(function(x,i){return i});for(var i=idx.length-1;i>0;i--){var j=Math.floor(Math.random()*(i+1)),t=idx[i];idx[i]=idx[j];idx[j]=t}return{o:idx.map(function(i){return o[i]}),a:idx.indexOf(a)}}
ml={t:'fix',sc:s0,st:0,wrong:0,pick:null,done:false,qs:[mk(s0.f,s0.fa),mk(s0.s,s0.sa),mk(s0.x,s0.xa)]}}
