function colv(){
if(!colony)return'<div class="card"><h1 style="font-size:26px">Colony survival: pick a planet</h1><p class="mut">Keep a growing crew alive for 30 sols. Each crew member eats, drinks and uses power every sol, so assign them to power, water and food. Dust storms, leaks and crop blight will test your reserves.</p></div><div class="grid">'+Object.keys(PL).map(function(k){var P=PL[k];return'<div class="card" style="margin:0"><h3>'+P.ico+' '+P.n+'</h3><p class="mut">'+P.d+'</p><span class="tag">'+P.diff+'</span><div style="margin-top:10px"><button class="btn" data-act="cstart" data-pl="'+k+'">Found colony</button></div></div>'}).join("")+'</div>';
var C=colony,A=C.a,used=A.p+A.w+A.f,cons=3*C.crew;
function g(n,v,c){return'<div class="gauge"><span>'+n+' '+Math.max(0,Math.round(v))+'</span><div class="bar"><i style="width:'+Math.max(0,Math.min(100,v))+'%;background:'+c+'"></i></div></div>'}
var h='<div class="card"><h2>'+PL[C.pl].ico+' '+PL[C.pl].n+': sol '+C.sol+' of 30</h2><p class="mut">'+PL[C.pl].d+'</p><p class="mut">Crew: '+C.crew+' · unassigned: '+(C.crew-used)+' · research: '+C.rp+' RP</p>'+g("⚡ Power",C.p,"var(--am)")+g("💧 Water",C.w,"var(--cy)")+g("🌱 Food",C.f,"var(--ok)")+'<p class="mut">'+esc(C.msg)+'</p>';
if(C.over)return h+'<h3>'+(C.win?"The colony thrives! +"+(50+20*PL[C.pl].lv)+" XP":"Colony lost: "+C.why+" +10 XP")+'</h3><button class="btn" data-act="cmenu">Choose another world</button></div>';
var rows=[["p","⚡ Solar and reactor"],["w","💧 Ice mining"],["f","🌱 Greenhouse"]];
return h+rows.map(function(r){var n=A[r[0]]*prod(r[0])-cons;return'<div class="row" style="margin:8px 0"><span>'+r[1]+'<br><span class="mut">net '+(n>=0?"+":"")+n+' per sol</span></span><span class="row"><button class="btn alt" data-ca="'+r[0]+'" data-cd="-1" aria-label="Remove crew">−</button><b>'+A[r[0]]+'</b><button class="btn alt" data-ca="'+r[0]+'" data-cd="1" aria-label="Add crew">+</button></span></div>'}).join("")+'<button class="btn" data-act="csol">End sol</button></div><div class="card"><h3>Research upgrades</h3><p class="mut">Earn 3 RP each sol. Upgrades are permanent.</p>'+UP.map(function(u){var own=C.u[u[0]];return'<div class="row" style="margin:8px 0"><span>'+u[1]+'<br><span class="mut">'+u[3]+'</span></span><button class="btn alt" data-up="'+u[0]+'" '+(own||C.rp<u[2]?"disabled":"")+'>'+(own?"Built":u[2]+" RP")+'</button></div>'}).join("")+'</div>'}
function cAlloc(k,dir){var A=colony.a,used=A.p+A.w+A.f;if(dir>0&&used>=colony.crew)return;if(dir<0&&A[k]<=0)return;A[k]+=dir;render()}
function cSol(){var C=colony,A=C.a;if(A.p+A.w+A.f<C.crew){toast("Assign every crew member first");return}
var P=PL[C.pl],m={p:prod("p"),w:prod("w"),f:prod("f")},r=Math.random(),msg="A quiet sol.";
if(r<.35){var E=P.ev[Math.floor(Math.random()*P.ev.length)];msg=E[0];if(E[2]==="x")m[E[1]]*=C.u.shield?(1+E[3])/2:E[3];else C[E[1]]-=C.u.shield?Math.ceil(E[3]/2):E[3]}
var cons=3*C.crew;
["p","w","f"].forEach(function(k){C[k]=Math.min(100,C[k]+A[k]*m[k]-cons)});
C.sol++;C.rp+=3;S.solDay=new Date().toDateString();
if(C.sol===9||C.sol===17||C.sol===25){C.crew++;msg+=" A new settler arrived, so demand rises."}
var low=C.p<=0?"power":C.w<=0?"water":C.f<=0?"food":"";
if(low){C.over=true;C.why="the colony ran out of "+low+".";gain(10,"surv")}
else if(C.sol>30){C.over=true;C.win=true;C.sol=30;gain(50+20*P.lv,"surv")}
else if(C.p<20||C.w<20||C.f<20)msg+=" Warning: a supply is below 20.";
C.msg=msg;render()}
